/** a bounded cache */
function createCache(max, { lru = false } = {}) {
  // Write your solution here
  const m = new Map();
  return {
    get: (k) => m.get(k),
    set: (k, v) => { m.set(k, v); },
    keys: () => [...m.keys()],
    size: () => m.size,
  };
}

